parameters.command:
sqlite3 -json "/data/arabic_dict.db" "
/* Query 1: Step 0 - Headword lookup for 'مقصر' */
SELECT e.id AS entry_id, e.headword, e.headword_norm, e.root, e.definitions_text, d.name_ar AS dict_name, d.source_type
FROM entries e
JOIN dictionaries d ON e.dictionary_id = d.id
WHERE e.headword_norm IN ('مقصر', 'المقصر')
ORDER BY d.source_type, d.death_year;

/* Query 2: Step 0.5 - English Bridge for 'shortener' */
SELECT e.id AS entry_id, e.headword, e.headword_norm, e.translation_en, d.name_ar AS dict_name
FROM entries e
JOIN dictionaries d ON e.dictionary_id = d.id
WHERE e.id IN (
    SELECT rowid FROM entries_translations_fts
    WHERE entries_translations_fts MATCH 'translation_en:\"shortener\"'
)
LIMIT 20;

/* Query 3: Step 0.5 - Arabic FTS for keywords 'تقصير', 'عامل' */
SELECT e.id AS entry_id, e.headword, e.headword_norm, e.definitions_text, d.name_ar AS dict_name
FROM entries e
JOIN dictionaries d ON e.dictionary_id = d.id
WHERE e.id IN (
    SELECT rowid FROM entries_fts
    WHERE entries_fts MATCH 'definitions_text:\"تقصير\" AND definitions_text:\"عامل\"'
)
LIMIT 20;
"
